ssl_certificate /etc/nginx/ssl/nginx.crt;
ssl_certificate_key /etc/nginx/ssl/nginx.key;

# Протоколы и шифры (TLS 1.2+)
ssl_protocols TLSv1.2 TLSv1.3;
ssl_ciphers "EECDH+AESGCM:EDH+AESGCM:AES256+EECDH:AES256+EDH";
ssl_prefer_server_ciphers on;
ssl_session_timeout 1d;
ssl_session_cache shared:SSL:10m;
ssl_stapling on;
ssl_stapling_verify on;
resolver 8.8.8.8 8.8.4.4 valid=300s;
resolver_timeout 5s;

# HTTP Strict Transport Security (HSTS)
add_header Strict-Transport-Security "max-age=31536000; includeSubDomains; preload" always;

# Дополнительные безопасные заголовки
add_header X-Content-Type-Options nosniff;
add_header X-Frame-Options DENY;
add_header X-XSS-Protection "1; mode=block";

root /var/www/example.com/html;
index index.html index.htm;

location / {
try_files $uri $uri/ =404;
}
}
```  
**Пояснения к ключевым параметрам**
- `ssl_protocols TLSv1.2 TLSv1.3` – отключаем устаревшие версии.
- `ssl_ciphers` – набор современных шифров, исключая слабые.
- `ssl_stapling` – ускоряет проверку сертификата через OCSP.
- `Strict-Transport-Security` – заставляет браузеры использовать HTTPS.

Измените файл `/etc/nginx/conf.d/ssl.conf` или соответствующий блок `server`.  
```nginx
server {
listen 443 ssl http2;
server_name example.com;

ssl_certificate /etc/letsencrypt/live/example.com/fullchain.pem;
ssl_certificate_key /etc/letsencrypt/live/example.com/privkey.pem;

# Современные протоколы
ssl_protocols TLSv1.2 TLSv1.3;

# Оптимизированный набор шифров
ssl_ciphers ECDHE-ECDSA-AES128-GCM-SHA256:ECDHE-RSA-AES128-GCM-SHA256:ECDHE-ECDSA-AES256-GCM-SHA384:ECDHE-RSA-AES256-GCM-SHA384;
ssl_prefer_server_ciphers off;

# HSTS (обязательно для безопасности)
add_header Strict-Transport-Security "max-age=63072000" always;
}
```  
> ⚠️ WARNING: После отключения TLS 1.1 пользователи со старыми браузерами (например, Internet Explorer 11 на Windows 7) не смогут получить доступ к сайту.

